package com.rohit.inventory.controller;
import com.rohit.inventory.dto.request.LoginRequest; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.service.AuthService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService service; public AuthController(AuthService service){this.service=service;} @PostMapping("/login") public ApiResponse<LoginResponse> login(@Valid @RequestBody LoginRequest request){return ApiResponse.success("Login successful",service.login(request));} @GetMapping("/me") public ApiResponse<UserResponse> me(@AuthenticationPrincipal UserDetails user){return ApiResponse.success("Current user retrieved successfully",service.me(user.getUsername()));} @PostMapping("/logout") public ApiResponse<Void> logout(@AuthenticationPrincipal UserDetails user){service.logout(user.getUsername());return ApiResponse.success("Logged out. Remove the access token from the client.",null);} }
